from datetime import datetime, timedelta

def seconds_until(hour, minute, now=None):
    now = now or datetime.now()
    target = now.replace(hour=hour, minute=minute, second=0, microsecond=0)
    if target <= now:
        target += timedelta(days=1)
    return int((target - now).total_seconds())

print(seconds_until(9, 30))

from datetime import time

def parse_time(text):
    parts = text.strip().split(':')
    if len(parts) not in (2, 3):
        raise ValueError(f'cannot parse time: {text!r}')
    nums = [int(p) for p in parts]
    hour, minute = nums[0], nums[1]
    second = nums[2] if len(nums) == 3 else 0
    if not (0 <= hour <= 23 and 0 <= minute <= 59 and 0 <= second <= 59):
        raise ValueError(f'time component out of range: {text!r}')
    return time(hour, minute, second)

print(parse_time('23:59:59'), parse_time('08:30'))
